    <style>
      :root {
        color-scheme: dark;
        --bg: #080b12;
        --panel: #111827;
        --panel-strong: #172033;
        --text: #f7fafc;
        --muted: #aab4c4;
        --line: rgba(255, 255, 255, 0.14);
        --accent: #8b5cf6;
        --accent-strong: #a78bfa;
        --danger: #fb7185;
        --danger-strong: #e11d48;
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.56);
        --focus: #facc15;
      }

      * {
        box-sizing: border-box;
      }

      html {
        min-height: 100%;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(139, 92, 246, 0.32), transparent 34rem),
          radial-gradient(circle at bottom right, rgba(225, 29, 72, 0.18), transparent 30rem),
          var(--bg);
      }

      a,
      button {
        -webkit-tap-highlight-color: transparent;
      }

      button {
        font: inherit;
      }

      :focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 4px;
      }

      .skip-link {
        position: fixed;
        top: 1rem;
        left: 1rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        color: #111827;
        background: var(--focus);
        transform: translateY(-150%);
        transition: transform 160ms ease;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        width: min(1120px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 2rem 0;
      }

      .site-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 2rem;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.75rem;
        font-weight: 800;
        letter-spacing: -0.03em;
      }

      .brand-mark {
        display: grid;
        width: 2.5rem;
        height: 2.5rem;
        place-items: center;
        border: 1px solid var(--line);
        border-radius: 0.9rem;
        background: linear-gradient(135deg, rgba(139, 92, 246, 0.9), rgba(225, 29, 72, 0.7));
        box-shadow: 0 12px 30px rgba(139, 92, 246, 0.24);
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        color: var(--accent-strong);
        font-size: 0.8rem;
        font-weight: 700;
        letter-spacing: 0.14em;
        text-transform: uppercase;
      }

      h1,
      h2 {
        margin: 0;
        letter-spacing: -0.045em;
      }

      h1 {
        max-width: 11ch;
        font-size: clamp(2.5rem, 7vw, 5.75rem);
        line-height: 0.92;
      }

      h2 {
        font-size: clamp(1.55rem, 5vw, 2.25rem);
        line-height: 1.05;
      }

      p {
        line-height: 1.65;
      }

      .preview-grid {
        display: grid;
        grid-template-columns: minmax(0, 1.08fr) minmax(18rem, 0.92fr);
        gap: clamp(1rem, 4vw, 3rem);
        align-items: center;
      }

      .hero-card,
      .detail-card {
        border: 1px solid var(--line);
        border-radius: 2rem;
        background: linear-gradient(145deg, rgba(17, 24, 39, 0.88), rgba(8, 11, 18, 0.72));
        box-shadow: var(--shadow);
      }

      .hero-card {
        overflow: hidden;
      }

      .image-frame {
        position: relative;
        min-height: clamp(22rem, 54vw, 38rem);
        background:
          linear-gradient(135deg, rgba(255, 255, 255, 0.08), transparent 38%),
          linear-gradient(160deg, #0f172a 0%, #312e81 45%, #be123c 100%);
      }

      .image-frame::before,
      .image-frame::after {
        position: absolute;
        content: "";
        border-radius: 999px;
        filter: blur(1px);
        opacity: 0.88;
      }

      .image-frame::before {
        width: 13rem;
        height: 13rem;
        top: 16%;
        right: 14%;
        background: radial-gradient(circle, #fde68a 0 18%, #f97316 19% 42%, transparent 43%);
      }

      .image-frame::after {
        right: -5rem;
        bottom: -3rem;
        width: 24rem;
        height: 18rem;
        border-radius: 45% 55% 0 0;
        background: linear-gradient(135deg, #111827, #020617 54%, #581c87);
        transform: rotate(-8deg);
      }

      .image-caption {
        position: absolute;
        left: 1.5rem;
        right: 1.5rem;
        bottom: 1.5rem;
        z-index: 1;
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        padding: 1rem;
        border: 1px solid rgba(255, 255, 255, 0.14);
        border-radius: 1.25rem;
        background: rgba(2, 6, 23, 0.72);
        backdrop-filter: blur(18px);
      }

      .image-caption strong,
      .meta strong {
        display: block;
      }

      .image-caption span,
      .meta span,
      .description {
        color: var(--muted);
      }

      .detail-card {
        padding: clamp(1.25rem, 4vw, 2rem);
      }

      .description {
        margin: 1rem 0 1.5rem;
        max-width: 38rem;
      }

      .meta-list {
        display: grid;
        gap: 0.85rem;
        margin: 0 0 1.5rem;
        padding: 0;
        list-style: none;
      }

      .meta {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        padding: 0.95rem 1rem;
        border: 1px solid var(--line);
        border-radius: 1rem;
        background: rgba(255, 255, 255, 0.04);
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.8rem;
      }

      .button {
        display: inline-flex;
        min-height: 2.75rem;
        align-items: center;
        justify-content: center;
        gap: 0.5rem;
        padding: 0.75rem 1rem;
        border: 1px solid transparent;
        border-radius: 999px;
        color: var(--text);
        font-weight: 800;
        cursor: pointer;
        transition:
          transform 160ms ease,
          border-color 160ms ease,
          background-color 160ms ease;
      }

      .button:hover {
        transform: translateY(-1px);
      }

      .button:active {
        transform: translateY(0);
      }

      .button-primary {
        background: linear-gradient(135deg, var(--accent), #c026d3);
        box-shadow: 0 18px 40px rgba(139, 92, 246, 0.28);
      }

      .button-muted {
        border-color: var(--line);
        background: rgba(255, 255, 255, 0.07);
      }

      .button-danger {
        background: var(--danger-strong);
        box-shadow: 0 18px 40px rgba(225, 29, 72, 0.26);
      }

      .trigger {
        border-color: rgba(251, 113, 133, 0.4);
        color: #ffe4e6;
        background: rgba(225, 29, 72, 0.18);
      }

      .trigger:hover {
        background: rgba(225, 29, 72, 0.28);
      }

      dialog {
        width: min(100% - 2rem, 31rem);
        max-height: min(42rem, calc(100vh - 2rem));
        padding: 0;
        border: 1px solid rgba(255, 255, 255, 0.18);
        border-radius: 1.7rem;
        color: var(--text);
        background: var(--panel);
        box-shadow: var(--shadow);
      }

      dialog:not([open]) {
        display: none;
      }

      dialog::backdrop {
        background:
          radial-gradient(circle at 50% 0%, rgba(139, 92, 246, 0.26), transparent 28rem),
          rgba(2, 6, 23, 0.78);
        backdrop-filter: blur(8px);
      }

      .dialog-panel {
        display: grid;
        gap: 1.15rem;
        padding: clamp(1.2rem, 5vw, 1.8rem);
      }

      .dialog-icon {
        display: grid;
        width: 3rem;
        height: 3rem;
        place-items: center;
        border-radius: 1rem;
        color: #fff1f2;
        background: rgba(225, 29, 72, 0.2);
        border: 1px solid rgba(251, 113, 133, 0.35);
      }

      .dialog-copy {
        margin: 0;
        color: var(--muted);
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap-reverse;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-top: 0.5rem;
      }

      .status-message {
        min-height: 1.5rem;
        margin-top: 1rem;
        color: #fecdd3;
        font-weight: 700;
      }

      @media (max-width: 760px) {
        .site-header,
        .preview-grid {
          display: block;
        }

        .site-header {
          margin-bottom: 1.25rem;
        }

        .brand {
          margin-bottom: 1rem;
        }

        .hero-card {
          margin-bottom: 1rem;
        }

        .image-caption,
        .meta,
        .dialog-actions {
          flex-direction: column;
          align-items: stretch;
        }

        .button {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        :root {
          --line: CanvasText;
          --focus: Highlight;
        }

        body,
        .hero-card,
        .detail-card,
        .image-caption,
        dialog,
        .button {
          forced-color-adjust: auto;
        }

        .brand-mark,
        .dialog-icon {
          border: 1px solid CanvasText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="root"></div>

    <script>
      const image = {
        title: "Crimson Dunes",
        collection: "Travel library",
        created: "May 2026",
        size: "18.4 MB",
        description:
          "A cinematic image preview with warm desert light, deep violet shadows, and a polished dark interface for managing the photo."
      };

      function Button({ className = "", type = "button", attributes = "", children }) {
        return `<button type="${type}" class="button ${className}" ${attributes}>${children}</button>`;
      }

      function Header() {
        return `
          <header class="site-header" aria-label="Image library header">
            <div class="brand">
              <span class="brand-mark" aria-hidden="true">✦</span>
              <span>Obsidian Gallery</span>
            </div>
            ${Button({ className: "button-muted", children: "Back to library" })}
          </header>
        `;
      }

      function ImageArtwork() {
        return `
          <section class="hero-card" aria-labelledby="preview-heading">
            <div class="image-frame" role="img" aria-label="Abstract sunset landscape for ${image.title}">
              <div class="image-caption">
                <div>
                  <strong id="preview-heading">${image.title}</strong>
                  <span>${image.collection}</span>
                </div>
                <div>
                  <strong>${image.created}</strong>
                  <span>Captured</span>
                </div>
              </div>
            </div>
          </section>
        `;
      }

      function ImageDetails() {
        return `
          <section class="detail-card" aria-labelledby="details-heading">
            <p class="eyebrow">Image preview</p>
            <h1 id="details-heading">${image.title}</h1>
            <p class="description">${image.description}</p>
            <ul class="meta-list" aria-label="Image details">
              <li class="meta"><strong>Collection</strong><span>${image.collection}</span></li>
              <li class="meta"><strong>Date added</strong><span>${image.created}</span></li>
              <li class="meta"><strong>File size</strong><span>${image.size}</span></li>
            </ul>
            <div class="actions" aria-label="Image actions">
              ${Button({ className: "button-primary", children: "Download image" })}
              ${Button({
                className: "trigger",
                attributes: 'aria-haspopup="dialog" aria-controls="delete-dialog"',
                children: "Delete image"
              })}
            </div>
            <p id="delete-status" class="status-message" aria-live="polite"></p>
          </section>
        `;
      }

      function DeleteDialog() {
        return `
          <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
            <form method="dialog" class="dialog-panel">
              <span class="dialog-icon" aria-hidden="true">!</span>
              <div>
                <h2 id="delete-dialog-title">Delete this image?</h2>
                <p id="delete-dialog-description" class="dialog-copy">
                  This will remove "${image.title}" from your library. This action cannot be undone.
                </p>
              </div>
              <div class="dialog-actions">
                ${Button({ className: "button-muted", attributes: 'value="cancel" data-cancel', children: "Cancel" })}
                ${Button({ className: "button-danger", attributes: 'value="delete" data-confirm', children: "Delete image" })}
              </div>
            </form>
          </dialog>
        `;
      }

      function App() {
        return `
          <div class="page-shell">
            ${Header()}
            <main id="main" class="preview-grid">
              ${ImageArtwork()}
              ${ImageDetails()}
            </main>
          </div>
          ${DeleteDialog()}
        `;
      }

      document.getElementById("root").innerHTML = App();

      const dialog = document.getElementById("delete-dialog");
      const trigger = document.querySelector(".trigger");
      const cancelButton = dialog.querySelector("[data-cancel]");
      const statusMessage = document.getElementById("delete-status");

      trigger.addEventListener("click", () => {
        dialog.showModal();
        cancelButton.focus();
      });

      dialog.addEventListener("close", () => {
        if (dialog.returnValue === "delete") {
          statusMessage.textContent = `"${image.title}" was deleted from your library.`;
        }
      });
    </script>
  </body>
</html>
