               ${Button({
                 className: "trigger",
                 attributes: 'aria-haspopup="dialog" aria-controls="delete-dialog"',
                 children: "Delete image"
               })}
             </div>
             <p id="delete-status" class="status-message" aria-live="polite"></p>
           </section>
         `;
       }

       function DeleteDialog() {
         return `
           <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
             <form method="dialog" class="dialog-panel">
               <span class="dialog-icon" aria-hidden="true">!</span>
               <div>
                 <h2 id="delete-dialog-title">Delete this image?</h2>
                 <p id="delete-dialog-description" class="dialog-copy">
                   This will remove "${image.title}" from your library. This action cannot be undone.
                 </p>
               </div>
               <div class="dialog-actions">
                 ${Button({ className: "button-muted", type: "submit", attributes: 'value="cancel" data-cancel', children: "Cancel" })}
                 ${Button({ className: "button-danger", type: "submit", attributes: 'value="delete" data-confirm', children: "Delete image" })}
               </div>
             </form>
           </dialog>
         `;
       }

       function App() {
         return `
           <div class="page-shell">
             ${Header()}
             <main id="main" class="preview-grid">
               ${ImageArtwork()}
               ${ImageDetails()}
             </main>
           </div>
           ${DeleteDialog()}
         `;
       }

       document.getElementById("root").innerHTML = App();

       const dialog = document.getElementById("delete-dialog");
       const trigger = document.querySelector(".trigger");
       const cancelButton = dialog.querySelector("[data-cancel]");
       const statusMessage = document.getElementById("delete-status");

       trigger.addEventListener("click", () => {
         dialog.showModal();
         cancelButton.focus();
       });

       dialog.addEventListener("close", () => {
         if (dialog.returnValue === "delete") {
           statusMessage.textContent = `"${image.title}" was deleted from your library.`;
         }
       });
     </script>
