    <script>
      const image = {
        title: "Crimson Dunes",
        collection: "Travel library",
        created: "May 2026",
        size: "18.4 MB",
        description:
          "A cinematic image preview with warm desert light, deep violet shadows, and a polished dark interface for managing the photo."
      };

      function Button({ className = "", type = "button", attributes = "", children }) {
        return `<button type="${type}" class="button ${className}" ${attributes}>${children}</button>`;
      }

      function Header() {
        return `
          <header class="site-header" aria-label="Image library header">
            <div class="brand">
              <span class="brand-mark" aria-hidden="true">*</span>
              <span>Obsidian Gallery</span>
            </div>
            ${Button({ className: "button-muted", children: "Back to library" })}
          </header>
        `;
      }

      function ImageArtwork() {
        return `
          <section class="hero-card" aria-labelledby="preview-heading">
            <div class="image-frame" role="img" aria-label="Abstract sunset landscape for ${image.title}">
              <div class="image-caption">
                <div>
                  <strong id="preview-heading">${image.title}</strong>
                  <span>${image.collection}</span>
                </div>
                <div>
                  <strong>${image.created}</strong>
                  <span>Captured</span>
                </div>
              </div>
            </div>
            <div class="image-toolbar" aria-label="Image management">
              ${Button({
                className: "trigger",
                attributes: 'aria-haspopup="dialog" aria-controls="delete-dialog"',
                children: "Delete image"
              })}
            </div>
          </section>
        `;
      }

      function ImageDetails() {
        return `
          <section class="detail-card" aria-labelledby="details-heading">
            <p class="eyebrow">Image preview</p>
            <h1 id="details-heading">${image.title}</h1>
            <p class="description">${image.description}</p>
            <ul class="meta-list" aria-label="Image details">
              <li class="meta"><strong>Collection</strong><span>${image.collection}</span></li>
              <li class="meta"><strong>Date added</strong><span>${image.created}</span></li>
              <li class="meta"><strong>File size</strong><span>${image.size}</span></li>
            </ul>
            <div class="actions" aria-label="Image actions">
              ${Button({ className: "button-primary", children: "Download image" })}
            </div>
            <p id="delete-status" class="status-message" aria-live="polite"></p>
          </section>
        `;
      }

      function DeleteDialog() {
        return `
          <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
            <form method="dialog" class="dialog-panel">
              <span class="dialog-icon" aria-hidden="true">!</span>
              <div>
                <h2 id="delete-dialog-title">Delete this image?</h2>
                <p id="delete-dialog-description" class="dialog-copy">
                  This will remove "${image.title}" from your library. This action cannot be undone.
                </p>
              </div>
              <div class="dialog-actions">
                ${Button({ className: "button-muted", type: "submit", attributes: 'value="cancel" data-cancel', children: "Cancel" })}
                ${Button({ className: "button-danger", type: "submit", attributes: 'value="delete" data-confirm', children: "Delete image" })}
              </div>
            </form>
          </dialog>
        `;
      }

      function App() {
        return `
          <div class="page-shell">
            ${Header()}
            <main id="main" class="preview-grid">
              ${ImageArtwork()}
              ${ImageDetails()}
            </main>
          </div>
          ${DeleteDialog()}
        `;
      }

      document.getElementById("root").innerHTML = App();

      const dialog = document.getElementById("delete-dialog");
      const trigger = document.querySelector(".trigger");
      const cancelButton = dialog.querySelector("[data-cancel]");
      const statusMessage = document.getElementById("delete-status");

      trigger.addEventListener("click", () => {
        dialog.showModal();
        cancelButton.focus();
      });

      dialog.addEventListener("close", () => {
        if (dialog.returnValue === "delete") {
          statusMessage.textContent = `"${image.title}" was deleted from your library.`;
        }
      });
    </script>
